($q$Bloody Mary mix$q$, 3, $q$Bottle and keep in the fridge. Shake before each use.$q$, NULL),
($q$Brew coffee concentrate$q$, 0, $q$Put the ground coffee in a clean container, add the cold water and stir so all the grounds are wet.$q$, NULL),
