($q$Brown sugar syrup$q$, 1, $q$Stir until fully dissolved, warming gently if needed.$q$, NULL),
($q$Brown sugar syrup$q$, 2, $q$Cool, bottle, label with the date and keep in the fridge.$q$, NULL),
($q$Butterfly pea gin$q$, 0, $q$Add the dried flowers to the gin in a clean jar or the bottle, seal and shake.$q$, NULL),
