($q$Chilli tincture$q$, 3, $q$Strain through a coffee filter into dropper bottles and label clearly as hot.$q$, NULL),
($q$Chilli-infused tequila$q$, 0, $q$Wearing gloves, halve the chillies and add them to the tequila in a clean jar.$q$, NULL),
